import React, { useState, useEffect } from 'react';

const Cart = () => {
  const [cartItems, setCartItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Get the userId from localStorage or Context
  const userId = localStorage.getItem('userId'); // Or get it from context/redux if used

  // Fetch cart items based on userId
  useEffect(() => {
    if (userId) {
      const fetchCartItems = async () => {
        try {
          setLoading(true); // Start loading
          setError(null); // Reset error

          // API call to fetch cart items from the backend (inventory and jewellery)
          const response = await fetch(`/api/cart/${userId}`);
          const data = await response.json();

          if (!response.ok) {
            throw new Error('Error fetching cart items');
          }

          // Merge inventory and jewellery items from the data
          const items = data.cartItems || []; // Assuming the API returns cart items
          setCartItems(items);
        } catch (err) {
          setError(err.message || 'Failed to load cart');
        } finally {
          setLoading(false); // Stop loading
        }
      };

      fetchCartItems();
    } else {
      setLoading(false);
      setError('No user logged in.');
    }
  }, [userId]);

  // Render cart content
  if (loading) {
    return <div>Loading cart...</div>;
  }

  if (error) {
    return <div>Error: {error}</div>;
  }

  if (!cartItems.length) {
    return <div>Your Cart is empty.</div>;
  }

  return (
    <div>
      <h1>Your Cart</h1>
      <div className="cart-items">
        {cartItems.map((item, index) => (
          <div key={index} className="cart-item">
            <img src={item.image || '/default-image.jpg'} alt={item.name} />
            <div className="item-details">
              <h3>{item.name}</h3>
              <p>Price: ${item.price}</p>
              <p>Fabric: {item.fabric}</p>
              <p>Color: {item.color}</p>
              <p>Occasion: {item.occasion}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Cart;
